#include <string>
#include <vector>

using namespace std;

class Solution {
public:
    int numWays(string s) {
        const int MOD = 1e9 + 7;
        int ones = 0;
        for (char c : s) if (c == '1') ones++;
        if (ones % 3 != 0) return 0;
        if (ones == 0) return (long long)(s.size() - 1) * (s.size() - 2) / 2 % MOD;

        int t = ones / 3, cnt = 0, a = 0, b = 0;
        for (char c : s) {
            if (c == '1') cnt++;
            if (cnt == t) a++;
            else if (cnt == 2 * t) b++;
        }
        return (long long)a * b % MOD;
    }
};
